import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const LoginPage = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const navigate = useNavigate();

  const handleSubmit = (event) => {
    event.preventDefault();
    // --- In a real app, you would send the email and password to your Django backend here ---
    console.log('Logging in with:', { email, password });

    // For now, we will just simulate a successful login and redirect to the dashboard.
    // The navigate() function changes the URL.
    navigate('/dashboard');
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-background-light dark:bg-background-dark">
      <div className="w-full max-w-md p-8 space-y-8 bg-card-light dark:bg-card-dark rounded-lg shadow-lg">
        <div className="flex justify-center">
            <div className="w-12 h-12 bg-blue-500 rounded-full"></div>
        </div>
        <h2 className="text-2xl font-bold text-center text-text-light dark:text-text-dark">
          University HRMS Portal
        </h2>
        <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
          <div className="space-y-4">
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-subtext-light dark:text-subtext-dark">
                Email address
              </label>
              <div className="mt-1">
                <input
                  id="email"
                  name="email"
                  type="email"
                  autoComplete="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full px-3 py-2 border rounded-md shadow-sm bg-background-light dark:bg-background-dark border-border-light dark:border-border-dark focus:outline-none focus:ring-primary focus:border-primary"
                  placeholder="you@university.edu"
                />
              </div>
            </div>
            <div>
              <label htmlFor="password" className="block text-sm font-medium text-subtext-light dark:text-subtext-dark">
                Password
              </label>
              <div className="mt-1">
                <input
                  id="password"
                  name="password"
                  type="password"
                  autoComplete="current-password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full px-3 py-2 border rounded-md shadow-sm bg-background-light dark:bg-background-dark border-border-light dark:border-border-dark focus:outline-none focus:ring-primary focus:border-primary"
                  placeholder="••••••••"
                />
              </div>
            </div>
          </div>

          <div>
            <button
              type="submit"
              className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-primary hover:bg-blue-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary"
            >
              Sign in
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default LoginPage;
